function processOrders(orders) {
  if (!orders || !Array.isArray(orders)) throw new Error('invalid');
  for (const o of orders) {
    if (!o.id || !o.amount || o.amount < 0) throw new Error('bad order: ' + o.id);
  }
  const transformed = orders.map(o => ({
    orderId: o.id, total: o.amount * 1.08,
    label: o.amount > 100 ? 'premium' : 'standard',
    ts: new Date().toISOString()
  }));
  let report = 'Order Report\n';
  let grandTotal = 0;
  for (const t of transformed) {
    report += t.orderId + ': $' + t.total.toFixed(2) + ' [' + t.label + ']\n';
    grandTotal += t.total;
  }
  report += 'Total: $' + grandTotal.toFixed(2);
  return { transformed, report };
}

